    def update(self, values, check_conflict=True, check_already_exists=True, path=""):
        """
        Update parameter values in the dictionary, with checks.

        Parameters
        ----------
        values : dict
            Dictionary of parameter values to update
        check_conflict : bool, optional
            Whether to check that a parameter that is in ``values`` has not already been
            set in ``self`` (default True)
        check_already_exists : bool, optional
            Whether to check that a parameter that is in ``values`` already exists in
            ``self`` (default True). Set to ``False`` when updating a parameter that is
            not in ``self`` yet.
        path : str, optional
            Path in which to update the parameters.
        """
        # check if parameter values are consistent
        for name, value in values.items():
            if not isinstance(value, pybamm.Symbol):
                if path:
                    name = path + name
                # check if the parameter is a "known input"
                if self._dict_items.get(name) is None:
                    # If not, raise error if check_already_exists
                    if check_already_exists:
                        try:
                            self._dict_items[name]
                        except KeyError as err:
                            raise KeyError(
                                f"Cannot update parameter '{name}' as it does not "
                                + "have a default value. "
                                + f"({err.args[0].split('. (')[1][:-1]}). If you are sure you want "
                                + "to update this parameter, use param.update({{name: value}}, "
                                + "check_already_exists=False)"
                            ) from err
                    else:
                        self._dict_items[name] = value

        # update the dictionary
        self._dict_items.update(values)
